CREATE TABLE IF NOT EXISTS hr_employee_bank(employee_bank_id TEXT PRIMARY KEY,employee_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,bank_name TEXT NOT NULL,account_number_masked TEXT NOT NULL,ifsc TEXT NOT NULL,is_primary BOOLEAN NOT NULL DEFAULT TRUE,status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hr_payroll_payment_batch(payment_batch_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,run_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',total_amount NUMERIC NOT NULL DEFAULT 0,approved BOOLEAN NOT NULL DEFAULT FALSE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(run_id));
CREATE TABLE IF NOT EXISTS hr_payroll_payment_instruction(instruction_id TEXT PRIMARY KEY,payment_batch_id TEXT NOT NULL,employee_id TEXT NOT NULL,amount NUMERIC NOT NULL,bank_id TEXT,reference TEXT,status TEXT NOT NULL DEFAULT 'PENDING',failure_reason TEXT,paid_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hr_payslip(payslip_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,employee_id TEXT NOT NULL,period_id TEXT NOT NULL,gross NUMERIC NOT NULL,deductions NUMERIC NOT NULL,net NUMERIC NOT NULL,status TEXT NOT NULL DEFAULT 'GENERATED',issued_at TIMESTAMP,UNIQUE(run_id,employee_id));
CREATE TABLE IF NOT EXISTS hr_statutory_settlement(settlement_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,run_id TEXT NOT NULL,statutory_code TEXT NOT NULL,amount NUMERIC NOT NULL,reference_number TEXT,status TEXT NOT NULL DEFAULT 'PENDING',paid_at TIMESTAMP,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hr_payroll_settlement_reconciliation(reconciliation_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,run_id TEXT NOT NULL,payroll_amount NUMERIC NOT NULL,bank_amount NUMERIC NOT NULL,statutory_amount NUMERIC NOT NULL,difference NUMERIC NOT NULL,status TEXT NOT NULL DEFAULT 'EXCEPTION',resolution_reason TEXT,resolved_by TEXT,resolved_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
